import{a as o}from"./chunk-VRQ32ULO.js";import{a}from"./chunk-2RJSKV3I.js";import"./chunk-U37H3HIF.js";var r=a(o,["Escolha onde seu trabalho fica guardado","Agora n\xE3o","A barra lateral continua mostrando “Sem c\xF3pia de seguran\xE7a” at\xE9 uma pasta ser escolhida. Clique nela quando quiser.","Seu trabalho n\xE3o tem c\xF3pia de seguran\xE7a","Criar um arquivo para levar","Agora sua corre\xE7\xE3o existe s\xF3 neste navegador, e limpar os dados do navegador a apagaria. Escolha uma pasta neste computador uma vez. Cada salvamento vai tamb\xE9m para l\xE1, com uma c\xF3pia de cada dia para voc\xEA voltar. Nada \xE9 enviado para a internet.","O trabalho mudou em outra janela enquanto isto estava aberto, ent\xE3o h\xE1 algo novo para escolher. Nada foi trazido ainda.","Isto mudou tanto aqui quanto no arquivo. Escolha o que voc\xEA quer em cada caso.","Os coment\xE1rios salvos do outro computador s\xE3o adicionados aos seus","Trazendo seu trabalho…","Mudan\xE7as em downloads que voc\xEA tem aqui",{one:"{n} aluno vem do arquivo",other:"{n} alunos v\xEAm do arquivo"},{one:"{n} exemplo chega ou muda",other:"{n} exemplos chegam ou mudam"},{one:"{n} arquivo muda: arquivos atrasados, leituras ou edi\xE7\xF5es do Word",other:"{n} arquivos mudam: arquivos atrasados, leituras ou edi\xE7\xF5es do Word"},"Isso n\xE3o terminou. Seu trabalho est\xE1 seguro, e antes foi feita uma c\xF3pia de prote\xE7\xE3o: Restaurar est\xE1 abaixo se algo parecer errado.","No arquivo","Este navegador ficou sem espa\xE7o, ent\xE3o isso n\xE3o terminou. Suas marca\xE7\xF5es e notas aqui n\xE3o foram substitu\xEDdas. Libere espa\xE7o em disco e tente de novo.","Trazer","Esquecido","Esquecido no outro computador, ent\xE3o \xE9 removido aqui tamb\xE9m","Continua esquecido",{one:"{n} mudan\xE7a em turmas, unidades ou listas",other:"{n} mudan\xE7as em turmas, unidades ou listas"},"Criado {when}",{one:"{n} download novo",other:"{n} downloads novos"},"Nada para trazer: o que est\xE1 aqui j\xE1 tem tudo deste arquivo.","Rubricas ou configura\xE7\xF5es que voc\xEA ainda n\xE3o tem aqui",{one:"{n} aula, arquivo ou configura\xE7\xE3o que seu planejamento aqui n\xE3o tem",other:"{n} aulas, arquivos ou configura\xE7\xF5es que seu planejamento aqui n\xE3o tem"},"Seu planejamento vem junto, com suas unidades, hor\xE1rio e arquivos. Vincule a pasta dele de novo se voc\xEA usa uma.","Este navegador pode n\xE3o ter espa\xE7o: precisa de cerca de {need} e tem cerca de {room}.","Antes \xE9 feita uma c\xF3pia de prote\xE7\xE3o de como tudo est\xE1 agora, ent\xE3o voc\xEA pode desfazer abaixo.",{one:"{n} download n\xE3o tem nada para trazer.",other:"{n} downloads n\xE3o t\xEAm nada para trazer."},"Recursos da escola adicionados ou alterados no outro computador",{one:"{n} configura\xE7\xE3o vem do arquivo",other:"{n} configura\xE7\xF5es v\xEAm do arquivo"},"O pequeno armazenamento deste navegador para listas e configura\xE7\xF5es est\xE1 cheio, ent\xE3o isso n\xE3o terminou. Suas marca\xE7\xF5es e notas aqui n\xE3o foram substitu\xEDdas.",{one:"{n} aluno fica igual aqui, porque esta c\xF3pia \xE9 mais recente",other:"{n} alunos ficam iguais aqui, porque esta c\xF3pia \xE9 mais recente"},{one:"{n} aluno",other:"{n} alunos"},"Exportar o que tenho","O navegador n\xE3o conseguiu guard\xE1-las, muitas vezes porque o computador est\xE1 sem espa\xE7o. Mantenha esta janela aberta, libere algum espa\xE7o e clique em Tentar de novo.","Suas marca\xE7\xF5es e notas mais recentes N\xC3O foram salvas.","Salvo. Seu trabalho est\xE1 seguro de novo.","Suas marca\xE7\xF5es e notas mais recentes foram salvas s\xF3 em parte, na pequena c\xF3pia r\xE1pida deste navegador.","Tentar de novo","Trazer trabalho","Digite a frase secreta de {name}. O arquivo inteiro \xE9 verificado antes de qualquer mudan\xE7a aqui.","Vai corrigir em outro computador ou trocar por um novo? Crie aqui um arquivo para levar e traga-o l\xE1. O mesmo vale para a volta.","Levar seu trabalho","Este \xE9 o exemplo, ent\xE3o ainda n\xE3o h\xE1 nada seu para levar.","Um arquivo","Um aluno (a corre\xE7\xE3o an\xF4nima est\xE1 ativada)","Trazer de volta","Alterado {when}","Escolha primeiro uma vers\xE3o para cada um.","em um momento anterior","Sem nota, coment\xE1rio ou marca\xE7\xF5es",{one:"{file}: {n} marca\xE7\xE3o",other:"{file}: {n} marca\xE7\xF5es"},"Na sua pasta","{file} vai para {key}","Este download foi esquecido, mas uma c\xF3pia tem trabalho feito depois disso.","Neste computador","Elas n\xE3o s\xE3o iguais neste navegador e na sua pasta, ent\xE3o nada foi escolhido por voc\xEA. At\xE9 voc\xEA decidir, cada lugar mant\xE9m a sua.","Decidir depois","Deixar esquecido","Corrigido {v}","Escolher a mais recente em cada caso","Sem turma","Nada configurado","Nada aqui","Desativado","Usar o que escolhi","Ativado","Um arquivo vai para um aluno","Pontos: {v}","Pontos, de {n}","Estas duas c\xF3pias n\xE3o t\xEAm os mesmos crit\xE9rios de rubrica, ent\xE3o cada uma mostra os seus.","Rubrica: {list}",{one:"Rubrica com {n} crit\xE9rio",other:"Rubrica com {n} crit\xE9rios"},"As notas ficam salvas de qualquer forma. Totais e porcentagens seguem a que voc\xEA escolher.","Folha de notas: {v}","Duas vers\xF5es para escolher","Verificando o arquivo…","Verificando o arquivo… {n} de {of}","Fechar","Decidir","Feito","Drives compartilhados","\xDAltima pasta","Meu Drive","Compartilhados comigo","Este arquivo est\xE1 danificado ou foi alterado depois de criado, ent\xE3o n\xE3o \xE9 confi\xE1vel. Nada mudou aqui. Crie um novo se puder.","Este arquivo foi criado por uma vers\xE3o mais nova do Grading Studio. Nada mudou aqui. Recarregue esta p\xE1gina para obter a vers\xE3o mais nova e tente de novo.","Esse n\xE3o \xE9 um backup do Grading Studio.","Esse n\xE3o \xE9 um arquivo para levar do Grading Studio.","Essa frase secreta n\xE3o abre este arquivo. Confira e tente de novo. Se tiver certeza dela, o arquivo pode estar danificado. Nada mudou aqui.","Escolha uma vez uma pasta neste computador, e cada salvamento vai para l\xE1 al\xE9m deste navegador, com uma c\xF3pia de cada dia para voltar. Escolha algo privado: ela guarda trabalhos de alunos. Quando o Chrome perguntar, escolha “Permitir em todas as visitas”. Se voc\xEA j\xE1 tem uma pasta do Grading Studio, escolha-a e seu trabalho volta.","Tudo voltou da sua pasta.","N\xE3o foi poss\xEDvel usar essa pasta. Tente outra.",{one:"Chegou trabalho mais recente da sua pasta para {n} aluno.",other:"Chegou trabalho mais recente da sua pasta para {n} alunos."},"Escolher uma pasta…","Feito. Seu trabalho agora tamb\xE9m \xE9 salvo em “{name}”.","Est\xE1 numa pasta chamada “{root}” dentro de “{name}”.","Uma c\xF3pia dos seus trabalhos, marca\xE7\xF5es, notas, coment\xE1rios, listas e rubricas fica guardada aqui, sem bot\xE3o de salvar para lembrar. Se este navegador for limpo algum dia, vincule a pasta de novo e tudo volta.","Alguns arquivos listados pela sua pasta n\xE3o est\xE3o mais nela ou est\xE3o danificados, ent\xE3o n\xE3o puderam voltar. Isso afeta: {list}. Suas marca\xE7\xF5es, notas e coment\xE1rios est\xE3o todos aqui. Para recuperar os trabalhos, solte o mesmo download de novo.","Usar outra pasta…","Chegou trabalho mais recente da sua pasta, ent\xE3o este download foi reaberto.","Parar de usar esta pasta","Parar de usar","Parar de salvar em “{name}”?","O que j\xE1 est\xE1 na pasta continua l\xE1. Nada nela \xE9 exclu\xEDdo. Seu trabalho continua neste navegador, sem uma segunda c\xF3pia.","N\xE3o est\xE1 mais salvando em uma pasta. Os arquivos da pasta continuam l\xE1.","A pasta guarda uma c\xF3pia de cada dia, e uma antes de qualquer mudan\xE7a grande. Voltar deixa suas marca\xE7\xF5es, notas, coment\xE1rios, arquivos atrasados, leituras, listas e configura\xE7\xF5es como estavam naquele momento. Os trabalhos ficam.","C\xF3pia do dia","Isso n\xE3o terminou. Seu trabalho pode ter voltado s\xF3 em parte: use Restaurar na c\xF3pia de prote\xE7\xE3o mais recente, abaixo.","Voltar","Voltar no tempo","Vincule uma pasta e ela guardar\xE1 uma c\xF3pia de cada dia para voc\xEA voltar.","Ainda n\xE3o h\xE1 c\xF3pias na pasta. A primeira \xE9 feita hoje.","Voltar para esta c\xF3pia de {when}?","Suas marca\xE7\xF5es, notas, coment\xE1rios, arquivos atrasados, leituras, listas e configura\xE7\xF5es voltam a como estavam naquele momento, neste navegador e na pasta. Os trabalhos ficam. Antes \xE9 feita uma c\xF3pia de como tudo est\xE1 agora, ent\xE3o d\xE1 para desfazer.","Abrir","Empacotando seu trabalho…","Empacotando seu trabalho… {n} de cerca de {of}","Corre\xE7\xE3o an\xF4nima","Avisos em arquivos novos e alterados","Trechos de v\xEDdeo","Turma","Link do Google Drive","Trabalho em grupo","Ilumina\xE7\xE3o","Arquivos movidos","Uma configura\xE7\xE3o","Caixas de corre\xE7\xE3o r\xE1pida","Quais leituras cada aluno v\xEA","Arquivos removidos e substitu\xEDdos","Devolvido aos alunos","Suas respostas sobre p\xE1ginas digitalizadas","Configurar rubrica","Caixas de cobertura e c\xF3digos de compartilhamento","V\xEDdeos girados para a posi\xE7\xE3o certa","Frase secreta","De novo, para confirmar","Escolha uma frase secreta de algumas palavras. Se voc\xEA esquecer, ningu\xE9m poder\xE1 abrir este arquivo, nem voc\xEA, mas seu trabalho aqui n\xE3o \xE9 afetado. Mesmo assim, guarde o arquivo em um lugar privado.","As duas n\xE3o s\xE3o iguais.","Use pelo menos 8 caracteres. Algumas palavras comuns funcionam bem.","Reconectar","Feito. Recarregando…","Remover deste computador","Seu \xFAltimo arquivo para levar foi criado {when}, depois da sua \xFAltima mudan\xE7a.","Removido deste computador. Recarregando…","Nem tudo p\xF4de ser removido. Feche as outras janelas do Grading Studio e tente de novo.","Sua pasta vinculada “{name}” n\xE3o \xE9 tocada: os arquivos dela ficam onde est\xE3o, e este navegador para de salvar nela.","Manter","Voc\xEA n\xE3o criou nenhum arquivo para levar a partir deste navegador, ent\xE3o o que foi feito aqui pode n\xE3o estar em nenhum outro lugar.",{one:"{n} download tem mudan\xE7as desde seu \xFAltimo arquivo para levar ({when}). Essas mudan\xE7as n\xE3o est\xE3o nesse arquivo.",other:"{n} downloads t\xEAm mudan\xE7as desde seu \xFAltimo arquivo para levar ({when}). Essas mudan\xE7as n\xE3o est\xE3o nesse arquivo."},"O planejamento n\xE3o \xE9 tocado. Isto n\xE3o pode ser desfeito.",{one:"Isto remove todo o trabalho dos alunos deste navegador: {n} download com seus trabalhos, marca\xE7\xF5es, notas e coment\xE1rios, al\xE9m de listas, unidades, rubricas, arquivos atrasados, leituras, edi\xE7\xF5es do Word, recursos da escola, exemplos e c\xF3pias de prote\xE7\xE3o.",other:"Isto remove todo o trabalho dos alunos deste navegador: {n} downloads com seus trabalhos, marca\xE7\xF5es, notas e coment\xE1rios, al\xE9m de listas, unidades, rubricas, arquivos atrasados, leituras, edi\xE7\xF5es do Word, recursos da escola, exemplos e c\xF3pias de prote\xE7\xE3o."},"Digite REMOVER para continuar","REMOVER","Uma c\xF3pia completa do seu trabalho \xE9 guardada neste navegador antes de qualquer coisa arriscada, como trazer trabalho, voltar no tempo ou come\xE7ar um novo ano. As tr\xEAs mais recentes s\xE3o mantidas. Os trabalhos n\xE3o v\xE3o nelas, j\xE1 que nunca mudam.","Feita pela vers\xE3o atual do app","C\xF3pias de prote\xE7\xE3o","Ainda n\xE3o h\xE1 c\xF3pias de prote\xE7\xE3o.","Restaurar","Restaurar a c\xF3pia de prote\xE7\xE3o de {when}?","Tudo volta a como estava naquele momento, e o que foi adicionado depois some. Os trabalhos ficam, ent\xE3o um download aberto depois mant\xE9m sua linha sem marca\xE7\xF5es. Antes \xE9 guardado como tudo est\xE1 agora, ent\xE3o d\xE1 para desfazer.","Parar","Levar meu trabalho comigo","Cria um arquivo protegido com tudo o que voc\xEA precisa para corrigir em outro computador: arquivos dos alunos, marca\xE7\xF5es, notas, coment\xE1rios, listas, rubricas, leituras, edi\xE7\xF5es do Word, arquivos adicionados e bons exemplos. Seu planejamento tamb\xE9m vai: aulas, unidades, hor\xE1rio e seus arquivos.","Feito: {name} ({size}). Abra o Grading Studio no outro computador e use Trazer trabalho. O mesmo vale para a volta.","Os trabalhos n\xE3o est\xE3o no arquivo para: {list}. S\xF3 as marca\xE7\xF5es e as notas foram. Voc\xEA vai precisar desses downloads no outro computador.","O arquivo n\xE3o terminou, ent\xE3o n\xE3o pode ser usado. Seu trabalho aqui est\xE1 bem. Tente de novo em um lugar com mais espa\xE7o.","Trabalho do Grading Studio {day}","Criar o arquivo","Trabalho do Grading Studio","Sem trabalhos para: {list}. Este navegador n\xE3o os guarda, ent\xE3o s\xF3 as marca\xE7\xF5es e as notas ir\xE3o no arquivo. Para levar tamb\xE9m os trabalhos, solte aqui antes cada um desses downloads.","N\xE3o foi poss\xEDvel gravar o arquivo ali. Tente outro lugar.","S\xF3 neste navegador. “{name}” precisa de um clique para reconectar","O Chrome precisa da sua permiss\xE3o para usar a pasta de novo. Escolha “Permitir em todas as visitas” e ele n\xE3o vai perguntar na pr\xF3xima vez","Verificando onde seu trabalho fica guardado…",{one:"{n} coisa para decidir sobre sua pasta",other:"{n} coisas para decidir sobre sua pasta"},"Duas vers\xF5es para escolher","Com backup no seu Google Drive","Cada altera\xE7\xE3o tamb\xE9m vai para a pasta oculta do Grading Studio no seu Google Drive","S\xF3 neste navegador. O disco de “{name}” est\xE1 cheio","{text}.","{text}. {tip}.","S\xF3 neste navegador. N\xE3o foi poss\xEDvel acessar “{name}”","Vai se atualizar sozinho assim que a pasta voltar","Sem c\xF3pia de seguran\xE7a. S\xF3 neste navegador","Limpar os dados deste navegador apagaria seu trabalho. Este navegador n\xE3o consegue salvar numa pasta, ent\xE3o crie um arquivo para levar quando terminar de corrigir","Apagar os dados deste navegador apagaria seu trabalho. Escolha uma pasta e cada salvamento tamb\xE9m vai para l\xE1","Neste navegador e na sua pasta “{name}”","Cada salvamento vai para os dois lugares. \xDAltimo salvamento na pasta \xE0s {time}","Cada salvamento vai para os dois lugares","S\xF3 neste navegador. O navegador ficou sem espa\xE7o, ent\xE3o “{name}” n\xE3o consegue se atualizar","Exemplo, guardado s\xF3 enquanto voc\xEA explora","Nada aqui \xE9 trabalho seu. Saia do exemplo e ele \xE9 apagado","Salvando na sua pasta “{name}”…","Salvando na sua pasta “{name}” ({prog})…","Seu trabalho j\xE1 est\xE1 neste navegador","Onde seu trabalho \xE9 salvo","o ano do arquivo","Suas turmas continuam em um novo ano com listas de turma vazias. Primeiro, tudo deste ano vai para um arquivo protegido, e o arquivo \xE9 verificado antes de qualquer coisa ser apagada aqui.","Arquivados: {list}",{one:"{n} turma, com suas unidades e cart\xF5es de atividade. Cada cart\xE3o mant\xE9m sua rubrica e suas caixas de corre\xE7\xE3o r\xE1pida. Sem trabalhos, notas ou coment\xE1rios.",other:"{n} turmas, com suas unidades e cart\xF5es de atividade. Cada cart\xE3o mant\xE9m sua rubrica e suas caixas de corre\xE7\xE3o r\xE1pida. Sem trabalhos, notas ou coment\xE1rios."},"O que continua","O arquivo n\xE3o foi lido de volta igual ao seu trabalho aqui, ent\xE3o n\xE3o \xE9 confi\xE1vel. Nada foi alterado aqui. Tente de novo em um lugar com mais espa\xE7o.","Datas de entrega e datas dos per\xEDodos, um ano depois","O arquivo n\xE3o terminou, ent\xE3o nada foi alterado aqui. Tente de novo em um lugar com mais espa\xE7o.","O ano que voc\xEA est\xE1 encerrando","Salvar o arquivo e come\xE7ar o novo ano","(pelas datas dos seus per\xEDodos)","Ano letivo","{year} em {file}, {when}","Ano do Grading Studio",{one:"{n} conjunto de trabalhos vai para o arquivo e sai deste navegador.",other:"{n} conjuntos de trabalhos v\xE3o para o arquivo e saem deste navegador."},"D\xEA um nome aos dois anos, como 2025–26 e 2026–27.","Este ano: {year}","Abrir um ano arquivado","Isso n\xE3o terminou. {now} est\xE1 seguro em {file}, e antes foi feita uma c\xF3pia de prote\xE7\xE3o: Restaurar est\xE1 abaixo. Recarregue antes de fazer qualquer outra coisa.","Abrir coloca aquele ano no lugar do que est\xE1 aqui agora. Primeiro, {now} \xE9 salvo em um arquivo pr\xF3prio com a mesma frase secreta, e verificado, para voc\xEA poder voltar do mesmo jeito.","Este navegador para de salvar na pasta “{name}”, que fica com o ano atual.","Salvar {now} e abrir {year}","Abrir {year}","O planejamento n\xE3o muda: as aulas do ano passado j\xE1 est\xE3o em Aulas anteriores.",{one:"O arquivo cont\xE9m {n} conjunto de trabalhos, com suas turmas, listas de turma, marca\xE7\xF5es e notas, criado {when}.",other:"O arquivo cont\xE9m {n} conjuntos de trabalhos, com suas turmas, listas de turma, marca\xE7\xF5es e notas, criado {when}."},"Escolha uma frase secreta de algumas palavras. Ningu\xE9m pode abrir o arquivo sem ela, nem voc\xEA, ent\xE3o anote-a em um lugar seguro.","Unidades do planejamento e o semestre, um ano depois. As aulas deste ano v\xE3o para Aulas anteriores, prontas para reutilizar.","Proteger o arquivo","Listas de turma, s\xF3 para turmas que mant\xEAm os mesmos alunos. Sen\xE3o, ficam vazias e a lista de acompanhamento \xE9 limpa.","O novo ano precisa de um nome diferente do que voc\xEA est\xE1 encerrando.","Salvando {year} em um arquivo…","Come\xE7ar um novo ano letivo","O novo ano n\xE3o terminou de ser configurado. Tudo de {year} est\xE1 seguro em {file}, e antes foi feita uma c\xF3pia de prote\xE7\xE3o: Restaurar est\xE1 abaixo se algo parecer errado.","{year} come\xE7ou","Suas turmas, unidades e cart\xF5es de atividade est\xE3o prontos. Cole os alunos de cada turma na aba Alunos dela se as listas estiverem vazias. Tudo de {from} est\xE1 em {file} ({size}), verificado. Guarde-o em um lugar seguro com a frase secreta. Abrir um ano arquivado traz ele de volta.","Come\xE7ando {year}…","Suas configura\xE7\xF5es, escala de notas, rubricas salvas e banco de coment\xE1rios ficam como est\xE3o.","O novo ano"],null);export{r as default};
